"highest_cents":5335600,"evaluation_passed":false}]}'::jsonb);
create temp table false_burns on commit drop as select * from jsonb_to_recordset((select data->'false_burns' from cleanup_manifest)) as x(event_id uuid,connector_id uuid,account_name text,minimum numeric,max_prior_cash numeric,proven_floor numeric);
create temp table restore_accounts on commit drop as select * from jsonb_to_recordset((select data->'restore' from cleanup_manifest)) as x(connector_id uuid,account_name text,account_id uuid,link_id uuid,life_id text,latest_at timestamptz,balance_cents bigint,floor_cents bigint,eod_floors jsonb,highest_cents bigint,evaluation_passed boolean);
create temp table scope_owners on commit drop as select distinct c.owner_user_id from public.ninja_connectors c join false_burns f on f.connector_id=c.id;
do $$ declare r record; saved_row record; session_row public.ninja_operation_probe_sessions%rowtype; link_row public.ninja_account_links%rowtype; changed integer; life jsonb; begin
 if (select count(*) from false_burns)<>81 or (select count(*) from restore_accounts)<>11 then raise exception 'REPAIR_MANIFEST_CHANGED'; end if;
 if exists(select 1 from public.audit_events where action='legacy_burn_cleanup_20261117') then raise exception 'LEGACY_CLEANUP_ALREADY_APPLIED'; end if;
 perform 1 from public.ninja_transition_states where connector_id in(select connector_id from false_burns) order by connector_id for update;
 insert into private_legacy_burn_cleanup_20261117.before_rows(table_name,row_id,data)
 select 'ninja_account_change_events',e.id::text,to_jsonb(e) from public.ninja_account_change_events e join false_burns f on f.event_id=e.id
 union all select 'ninja_transition_states',s.connector_id::text,to_jsonb(s) from public.ninja_transition_states s where connector_id in(select connector_id from false_burns)
 union all select 'ninja_account_links',l.id::text,to_jsonb(l) from public.ninja_account_links l where connector_id in(select connector_id from false_burns)
 union all select 'accounts',a.id::text,to_jsonb(a) from public.accounts a where workspace_id in(select id from public.workspaces where owner_user_id in(select owner_user_id from scope_owners))
 union all select 'purchases',p.id::text,to_jsonb(p) from public.purchases p join public.accounts a on a.id=p.account_id where a.workspace_id in(select id from public.workspaces where owner_user_id in(select owner_user_id from scope_owners))
 union all select 'daily_controls',d.id::text,to_jsonb(d) from public.daily_controls d join public.periods p on p.id=d.period_id join public.workspaces w on w.id=p.workspace_id where w.owner_user_id in(select owner_user_id from scope_owners)
 union all select 'operation_entries',e.id::text,to_jsonb(e) from public.operation_entries e join public.periods p on p.id=e.period_id join public.workspaces w on w.id=p.workspace_id where w.owner_user_id in(select owner_user_id from scope_owners)
 union all select 'daily_control_participants',d.daily_control_id::text||':'||d.account_id::text,to_jsonb(d) from public.daily_control_participants d join public.periods p on p.id=d.period_id join public.workspaces w on w.id=p.workspace_id where w.owner_user_id in(select owner_user_id from scope_owners)
 union all select 'ninja_operation_batches',b.id::text,to_jsonb(b) from public.ninja_operation_batches b join public.ninja_connectors c on c.id=b.connector_id where c.owner_user_id in(select owner_user_id from scope_owners)
 union all select 'ninja_operation_batch_members',m.batch_id::text||':'||m.session_id::text,to_jsonb(m) from public.ninja_operation_batch_members m join public.ninja_operation_batches b on b.id=m.batch_id join public.ninja_connectors c on c.id=b.connector_id where c.owner_user_id in(select owner_user_id from scope_owners)
 on conflict do nothing;
 for r in select f.*,e.source_event_id,e.occurred_at from false_burns f join public.ninja_account_change_events e on e.id=f.event_id loop
  select * into strict session_row from public.ninja_operation_probe_sessions where connector_id=r.connector_id and account_name=r.account_name and opening_event_id=split_part(r.source_event_id,':',2)::bigint order by updated_at desc limit 1;
  if session_row.minimum_net_liquidation is distinct from r.minimum or r.minimum<=r.proven_floor then raise exception 'BURN_PROOF_CHANGED: %',r.event_id; end if;
  if not exists(select 1 from public.ninja_account_change_events where id=r.event_id and event_type='burned' and resolution_status<>'dismissed' and connector_id=r.connector_id and from_account_name=r.account_name) then raise exception 'BURN_STATUS_CHANGED: %',r.event_id; end if;
  update public.ninja_account_change_events set resolution_status='dismissed',reason=reason||' Revisión17/11: mínimo de la operación supera el máximo piso EOD histórico respaldado por inventarios anteriores ('||r.proven_floor||' USD). Inferencia retrospectiva falsa; se conservan quemas reales posteriores.' where id=r.event_id;
 end loop;
 for r in select * from restore_accounts loop
  select * into strict link_row from public.ninja_account_links where id=r.link_id and connector_id=r.connector_id and account_id=r.account_id and external_account_name=r.account_name and closure_reason='burned' and closed_at is not null for update;
  if exists(select 1 from public.ninja_account_change_events e where e.connector_id=r.connector_id and e.from_account_name=r.account_name and e.event_type='burned' and e.automatic and e.resolution_status<>'dismissed' and e.occurred_at>=link_row.first_seen_at) then raise exception 'VALID_LATER_BURN: %',r.account_name; end if;
  if exists(select 1 from public.ninja_operation_probe_sessions where connector_id=r.connector_id and account_name=r.account_name and status='open') then raise exception 'ACCOUNT_CURRENTLY_OPEN: %',r.account_name; end if;
  if r.balance_cents<=r.floor_cents or not exists(select 1 from public.ninja_inventory_snapshots h cross join lateral jsonb_array_elements(h.accounts)a where h.connector_id=r.connector_id and h.observed_at=r.latest_at and a->>'accountName'=r.account_name and round((a->>'cashValue')::numeric*100)=r.balance_cents) then raise exception 'LATEST_CASH_NOT_PROVEN: %',r.account_name; end if;
  select x into strict life from public.ninja_transition_states st cross join lateral jsonb_array_elements(st.state->'lives')x where st.connector_id=r.connector_id and x->>'lifeId'=r.life_id;
  if life->'tracked'->>'lastBusinessDate'>to_char(r.latest_at at time zone 'UTC','YYYY-MM-DD') then raise exception 'NEWER_LIFE_OBSERVATION: %',r.account_name; end if;
  insert into public.ninja_account_change_events(connector_id,connection_name,event_type,from_account_name,from_life_id,occurred_at,source_event_id,automatic,resolution_status,reason)
  values(r.connector_id,link_row.connection_name,'burn_reversed',r.account_name,r.life_id,r.latest_at,'legacy-burn-restore-20261117:'||r.life_id,true,'automatic','Falsa quema retrospectiva descartada; sesiones posteriores y saldo original corroboran continuidad. Se recupera la misma cuenta y compra.');
  -- Explicit, evidence-checked repair; the generic resurrection trigger stays disabled.
  update public.ninja_account_links set closed_at=null,closure_reason=null where id=r.link_id;
  update public.accounts set state='live',state_origin='automatic',updated_at=now() where id=r.account_id;
  if not exists(select 1 from public.ninja_account_links x join public.accounts a on a.id=x.account_id where x.id=r.link_id and x.closed_at is null and a.state='live') then raise exception 'EXPLICIT_RECOVERY_NOT_APPLIED'; end if;
  update public.ninja_transition_states st set state=jsonb_set(st.state,'{lives}',(select jsonb_agg(case when x->>'lifeId'=r.life_id then x||jsonb_build_object('status','active','tracked',(x->'tracked')||jsonb_build_object('balanceInCents',r.balance_cents,'burnFloorInCents',r.floor_cents,'highestEodBalanceInCents',r.highest_cents,'lastBusinessDate',to_char(r.latest_at at time zone 'UTC','YYYY-MM-DD'),'balanceStatus','verified','eodBurnFloors',coalesce(x->'tracked'->'eodBurnFloors','{}'::jsonb)||r.eod_floors,'reachedEvaluationTarget',coalesce((x->'tracked'->>'reachedEvaluationTarget')::boolean,false) or r.evaluation_passed)) else x end) from jsonb_array_elements(st.state->'lives')x)),revision=revision+1,updated_at=now() where st.connector_id=r.connector_id;
 end loop;
 -- Financial ledger and original purchase amounts MUST remain unchanged in this phase.
 for saved_row in select * from private_legacy_burn_cleanup_20261117.before_rows where table_name in('daily_controls','operation_entries','purchases') loop
  execute format('select count(*) from public.%I t where t.id::text=$1 and to_jsonb(t)=$2',saved_row.table_name) into changed using saved_row.row_id,saved_row.data;
  if changed<>1 then raise exception 'UNEXPECTED_FINANCIAL_CHANGE: % %',saved_row.table_name,saved_row.row_id; end if;
 end loop;
 insert into public.audit_events(actor_user_id,entity_table,entity_id,action,current_data,reason)
 values('f2f5f816-ec4f-46e1-b216-5267aeadc635','ninja_account_change_events','00000000-0000-4000-8000-202611170081','legacy_burn_cleanup_20261117',jsonb_build_object('false_events',81,'restored_accounts',11,'backup','private_legacy_burn_cleanup_20261117.before_rows'),'Revisión global autorizada de falsas quemas previas al arreglo; fuentes originales conservadas y eventos reales posteriores respetados.');
end$$;
select 'Avisos falsos descartados' as control,count(*)::text as resultado from public.ninja_account_change_events where id in(select event_id from false_burns) and resolution_status='dismissed' union all select 'Cuentas recuperadas',count(*)::text from public.accounts where id in(select account_id from restore_accounts) and state='live';
rollback;
